export type ConflictPack='Deep secrets'|'Petty grievances'|'Sibling rivalries'|'In-law boundaries'|'Money and business'|'Estrangement'|'Addiction and cover-ups'|'Medical proxies';
export interface PackedConflict {
  key:string;pack:ConflictPack;title:string;question:string;
  a:[string,string,string];b:[string,string,string];cost?:[number,number];
}
// Original adaptations of the user's scenario outlines. Costs are fictional game balancing values.
const FAMILY_CONFLICTS:PackedConflict[]=[
  {key:'second-family',pack:'Deep secrets',title:'The second family',question:'You find proof that Dad has another family two states away. Mom does not know. What do you do?',a:['Tell Mom immediately.','Mom knows you did not keep her in the dark.','Separation talks begin. Money and loyalties become contested; the family cannot assume how the marriage will end.'],b:['Confront Dad privately and hold the secret over him.','Dad listens because you now have leverage.','Carrying the secret consumes your attention. The relationship becomes a bargain built on fear of exposure.']},
  {key:'dna-surprise',pack:'Deep secrets',title:'The DNA surprise',question:'A consumer DNA result suggests Casey may be your half-sibling. It is unexpected information, not a complete family history. What do you do?',a:['Share the result privately with Casey.','Casey gets to examine information about their own identity.','Casey confronts Mom before the family has clarified the result. Questions about parentage become a crisis of trust.'],b:['Hide the result and delete your account.','You postpone a painful conversation.','Deleting your account does not erase every copy. Casey later learns you withheld information and interprets it through years of favoritism.']},
  {key:'golden-lie',pack:'Deep secrets',title:'The golden child’s lie',question:'Casey left medical school a year ago but has been pretending to attend. The parents still use Casey as their example of success. What do you do?',a:['Expose the lie at a family gathering.','The perfect-child story finally collapses.','The parents focus on your public delivery and call it jealousy. Casey feels humiliated rather than helped.'],b:['Use the secret to demand favors from Casey.','Casey complies because they fear exposure.','The favors accumulate into resentment. Casey eventually tells the family about your coercion as well as their own lie.']},
  {key:'inlaw-affair',pack:'Deep secrets',title:'The in-law affair',question:'You see Casey’s spouse kissing someone else at a bar. Casey has not mentioned an open relationship. What do you do?',a:['Tell Casey privately what you saw, without embellishing.','Casey receives information relevant to their relationship.','Casey believes their spouse’s denial and accuses you of interfering. Being honest does not guarantee being believed.'],b:['Give the spouse a day to explain it to Casey.','You offer them a chance to speak directly.','The spouse uses the time to claim you are trying to break them up. Your delayed account now competes with an established story.']},
  {key:'forged-signature',pack:'Deep secrets',title:'The forged signature',question:'You find records suggesting one parent forged the other’s signature on a loan tied to a hidden addiction. What do you do?',a:['Show the affected parent the records.','They can seek independent advice and understand the risk.','The accusation fractures loyalties. Investigation and legal consequences are possible, but the family cannot decide the outcome itself.'],b:['Contribute $800 and keep the borrowing secret.','An immediate payment is made without a public confrontation.','You lose $800 without resolving the deception or addiction. The family starts treating your money as the solution to the next crisis.'],cost:[0,800]},
  {key:'phantom-grandparent',pack:'Deep secrets',title:'The phantom grandparent',question:'Old papers suggest a grandparent has used a different identity since 1974 and concealed a criminal past. What do you choose?',a:['Investigate the history.','You uncover a forgotten family connection and a possible legacy claim.','An unwelcome person from the past contacts the family. What looked like an inheritance story now has a cost in privacy.'],b:['Destroy the papers.','You remove the documents you found, hoping to stop the past resurfacing.','Other records may still exist. The grandparent discovers what you destroyed and sees it as a betrayal, not guaranteed protection.']},
  {key:'stolen-heirloom',pack:'Deep secrets',title:'The stolen heirloom',question:'You learn that an antique your aunt calls a family treasure was stolen from a friend years ago. What do you do?',a:['Arrange to return it without taking public credit.','The original family gets its property back.','Your aunt starts accusing relatives of stealing from her. The returned object leaves a new trail of suspicion in the household.'],b:['Keep repeating the family’s ownership story.','Your aunt remains pleased with your loyalty.','The original owner’s children publicly challenge the story. The family must explain why loyalty depended on hiding the theft.']},
  {key:'secret-diagnosis',pack:'Deep secrets',title:'The secret diagnosis',question:'You accidentally see paperwork suggesting a parent has a terminal illness they have not shared. What do you do?',a:['Bring the family together and disclose what you saw.','Relatives can begin asking how to help and prepare.','The parent feels their privacy and control were taken away. They withdraw from family conversations about care; their medical decisions remain their own.'],b:['Keep silent and behave as usual.','The parent keeps control of when to share the news for now.','When the siblings eventually learn the news, they are angry that you knew. Privacy and the wish for more time collide.']},
  {key:'unclaimed-child',pack:'Deep secrets',title:'The unclaimed child',question:'A stranger contacts you with details suggesting they may be a child your parents placed for adoption. Their claim has not been independently confirmed. What do you do?',a:['Agree to a private meeting before telling the parents.','You hear another account of the family’s history.','The person later ignores a request to slow contact. You need firmer boundaries while the family is still unsure what is true.'],b:['Block the account and tell your parents.','You stop direct contact while the adults address the claim.','The parents become withdrawn and distressed. Blocking a message does not resolve the history or the possibility of a connection.']},
  {key:'will-sabotage',pack:'Deep secrets',title:'The will sabotage',question:'A relative pressures a confused grandparent to change their will. You witness the pressure. What do you choose?',a:['Interrupt and ask for independent support for the grandparent.','You challenge coercion and protect room for the grandparent’s own wishes.','The relative begins spreading lies about your motives. Protecting someone vulnerable makes you a target.'],b:['Demand a share in exchange for silence.','You join a coercive bargain in pursuit of a possible inheritance.','The bargain ties you to the exploitation. This unlocks the Villain route and closes repair choices in later core-conflict aftermaths.']},
  {key:'dietary-sabotage',pack:'Petty grievances',title:'The dietary sabotage',question:'The only dish you can eat contains meat broth despite three reminders. What do you do?',a:['Order a $25 pizza and announce why.','You get a meal that works for you.','The cook calls you dramatic, and the family spends more time judging the announcement than the ignored reminders.'],b:['Eat bread without commenting.','You avoid an argument during dinner.','You leave hungry and resentful. Nobody agrees to change the next meal.'],cost:[25,0]},
  {key:'regifted-insult',pack:'Petty grievances',title:'The regifted insult',question:'Casey gives you the same cheap candle you gave them three years ago. You recognize the label. What do you do?',a:['Point it out in front of everyone.','Casey is embarrassed and the careless gesture is exposed.','The parents defend Casey and the gift exchange becomes another argument about who is too sensitive.'],b:['Smile and save it for next year.','The afternoon continues peacefully.','You begin planning to return the candle next holiday. A small insult becomes a recurring ritual of resentment.']},
  {key:'photo-tag',pack:'Petty grievances',title:'The unflattering photo tag',question:'Your aunt posts a photo you dislike and refuses to remove it because she looks good. What do you do?',a:['Untag yourself, report your concern, and block her.','You limit what appears on your own account; removal elsewhere is not guaranteed.','Your aunt tells relatives you cut her out of your life over a photograph.'],b:['Post an unflattering photo of her in return.','She experiences the embarrassment she dismissed.','Both families can see the retaliation. The argument becomes a public contest over who can humiliate whom.']},
  {key:'containers',pack:'Petty grievances',title:'The Tupperware hostage',question:'A relative says your food containers are lost, but you can see them in the fridge. What do you do?',a:['Take your containers back while they are out of the room.','Your containers come home.','The relative treats your action as permission to take one of your belongings later. The dispute becomes reciprocal.'],b:['Let it go and spend $40 replacing them.','You avoid arguing over containers.','The cost is yours, and the relative asks to borrow something more valuable next time.'],cost:[0,40]},
  {key:'recipe',pack:'Petty grievances',title:'The recipe gatekeeper',question:'A relative gives you a recipe but appears to have left out a crucial ingredient. What do you do?',a:['Watch closely while they cook to find the missing step.','You discover why your version tasted different.','They notice the scrutiny and accuse you of snooping. The recipe becomes a dispute about trust and credit.'],b:['Bring a $35 store-bought alternative.','Guests enjoy an option that does not depend on the guarded recipe.','The relative calls it an attack on family tradition and dismisses the meal as commercial garbage.'],cost:[0,35]},
  {key:'thermostat',pack:'Petty grievances',title:'The thermostat war',question:'Someone keeps changing the thermostat between too hot and too cold. What do you do?',a:['Spend $60 on a thermostat lockbox.','You control the setting for now.','A frustrated relative breaks the lockbox. The original disagreement remains and another repair is needed.'],b:['Wear a coat indoors and say nothing.','You avoid another argument over the temperature.','The visit stays uncomfortable, leaving you irritable when the next small disagreement arrives.'],cost:[60,0]},
  {key:'driveway',pack:'Petty grievances',title:'The driveway block-in',question:'Your cousin blocks your car, goes to sleep, and will not answer while you need to leave for work. What do you do?',a:['Sound the horn until they wake up.','The cousin moves the car and you can leave.','The entire house wakes up and complains about your noise instead of the blocked driveway.'],b:['Pay $35 for a rideshare.','You leave without waking the house.','You bear the cost, and nobody agrees that blocking you in was unacceptable.'],cost:[0,35]},
  {key:'backhanded',pack:'Petty grievances',title:'The backhanded compliment',question:'A parent praises Casey while publicly offering unwanted advice about your life. What do you do?',a:['Reply with a pointed insult.','The advice stops for the moment.','Your tone becomes the subject. The parent presents your anger as proof that their criticism was justified.'],b:['Smile and change the subject.','You deny the argument an audience.','The remark stays with you, and no boundary has been stated about future comments.']},
  {key:'group-chat',pack:'Petty grievances',title:'The group chat ghosting',question:'Your important planning question is ignored while the family chat discusses something trivial. What do you do?',a:['Leave the chat.','You stop watching the question disappear under unrelated messages.','You miss a later update and must find another way to coordinate with the family.'],b:['Ignore their next request in return.','The small act of retaliation feels satisfying.','More people stop answering practical questions. The chat becomes less useful for everyone.']},
  {key:'couch',pack:'Petty grievances',title:'The couch claim',question:'A visiting relative occupies your favorite seat and covers it with belongings all week. What do you do?',a:['Move their things to the floor when they leave.','You reclaim the seat.','They start moving your belongings in return. A place to sit becomes a week of small territorial disputes.'],b:['Take the uncomfortable chair.','The visitor sees you as an accommodating host.','You stay uncomfortable and irritated, while they assume the arrangement works for everyone.']},
  {key:'milestone',pack:'Sibling rivalries',title:'The milestone hijack',question:'During your celebration speech, Casey interrupts to announce a pregnancy. What do you do?',a:['Take the microphone back and mock the timing.','Attention returns to your event.','Guests remember the clash, and the family accuses you of jealousy.'],b:['Offer a toast to Casey.','Guests praise your generosity.','The rest of the event revolves around the announcement. Your own milestone feels unfinished.']},
  {key:'shrine',pack:'Sibling rivalries',title:'The shrine room',question:'Your old bedroom is now a gym, while Casey’s room has been left untouched. What do you do during your visit?',a:['Use Casey’s room.','The unequal arrangements can no longer go unmentioned.','Casey objects to the intrusion, and the parents discuss your behavior instead of the unequal treatment.'],b:['Sleep on the gym floor without asking for another arrangement.','You avoid a room dispute.','You sleep badly, and the family may not understand the point you hoped the arrangement would make.']},
  {key:'bailout-discrepancy',pack:'Sibling rivalries',title:'The bailout discrepancy',question:'Your parents refuse $500 for your car repair while paying for Casey’s luxury vacation. What do you do?',a:['Show them the receipts and ask about the difference.','The claim that both siblings face the same rules is challenged.','They accuse you of snooping and threaten to stop offering financial help.'],b:['Take a fictional $500 short-term loan with a $150 fee.','You obtain the repair money without your parents’ permission.','The repair uses the $500 and repayment comes due: $650 leaves your balance. Resentment and financial pressure accumulate.']},
  {key:'revisionist',pack:'Sibling rivalries',title:'The revisionist history',question:'Your parents describe a hurtful childhood bullying incident as cute sibling bonding. What do you do?',a:['Explain how the incident actually felt.','Your account of your own experience is spoken aloud.','They call you too sensitive and complain that you spoiled a happy memory.'],b:['Laugh along.','You avoid another exhausting dispute over the past.','Casey repeats an old insult, interpreting the laughter as permission.']},
  {key:'spill',pack:'Sibling rivalries',title:'The accidental spill',question:'Casey damages something expensive with a spilled drink and gives the same mocking apology you remember from childhood. What do you do?',a:['Damage Casey’s phone in retaliation.','Casey immediately feels a similar loss.','Both sides now have property damage to justify the next act of revenge.'],b:['Hand Casey a towel and a repair invoice.','You make the cost explicit without retaliating.','Casey refuses to pay and complains to the family that you care only about money.']},
  {key:'toast',pack:'Sibling rivalries',title:'The sabotaged toast',question:'Casey’s toast at your event turns into a series of humiliating childhood stories. What do you do?',a:['Interrupt with a secret Casey wanted kept private.','The room stops laughing at you.','Both people are exposed and the event is derailed. The audience cannot unhear either story.'],b:['Let Casey finish, then offer a sincere thank you.','The contrast makes the cruelty more visible to some guests.','The recording still includes the insults. Choosing restraint does not erase what happened.']},
  {key:'grandchild',pack:'Sibling rivalries',title:'The golden grandchild',question:'In this family vignette, the grandparents give Casey’s child a tablet and your child a cheap coloring book. What do you do?',a:['Throw away the coloring book in front of them.','You make the disparity impossible to ignore.','The grandparents leave angrily, and the children witness another adult conflict.'],b:['Buy your child a $300 tablet later.','Your child gets a comparable gift.','You absorb the expense while the grandparents face no agreement about fairer treatment.'],cost:[0,300]},
  {key:'career-comparison',pack:'Sibling rivalries',title:'The career comparison',question:'A parent introduces you using Casey’s prestigious job title, then loudly corrects the mistake. What do you do?',a:['Introduce the parent by an embarrassing failure.','They experience the public humiliation they just dismissed.','Their friends see the retaliation without knowing its history, and the parent holds a grudge.'],b:['State your own job clearly and calmly.','You represent yourself on your own terms.','The comparison still hurts, even though you kept your composure.']},
  {key:'stolen-narrative',pack:'Sibling rivalries',title:'The stolen narrative',question:'Casey claims that a story from your life happened to them. What do you do?',a:['Ask for a detail only the person who experienced it would know.','The claim falls apart in front of the group.','The conversation dies in an awkward silence, and Casey blames you for the embarrassment.'],b:['Let the claim pass.','You avoid a public contest over the story.','Casey repeats it to new people, making the boundary harder to establish later.']},
  {key:'excluded-trip',pack:'Sibling rivalries',title:'The exclusionary vacation',question:'You learn your parents took Casey’s family to Hawaii without inviting you. They say they assumed you could not afford it. What do you do?',a:['Spend $700 on a solo trip to show them up.','You enjoy a trip chosen entirely by you.','Your balance falls by $700, and part of the experience revolves around proving something to the people who excluded you.'],b:['Mute their accounts and take a month of distance.','You reduce the constant reminders and make room for yourself.','Relatives describe your silence as coldness instead of asking why you needed distance.'],cost:[700,0]},
  {key:'bridal',pack:'In-law boundaries',title:'The bridal blackout',question:'In this wedding vignette, your mother-in-law arrives in a white lace gown that resembles a bridal dress. What do you do?',a:['Arrange for wine to be spilled on it.','She changes out of the gown.','She spends the reception describing the damage, and the deliberate humiliation becomes its own story.'],b:['Pay $80 to recolor the dress in the official photos.','Your copies of the photographs have the look you wanted.','She refuses to display them and argues about the edit long after the wedding.'],cost:[0,80]},
  {key:'honeymoon',pack:'In-law boundaries',title:'The honeymoon crashers',question:'Your in-laws appear at the resort where you planned a private honeymoon. What do you do?',a:['Pay $1200 to move to another destination.','You recover privacy and state a firm boundary.','The cost is real, and your spouse receives guilt-laden calls about abandoning the parents.'],b:['Stay in the room and decline joint activities.','You deny the unplanned family vacation.','You miss experiences you paid for, while frustration with the intrusion spills into your time together.'],cost:[1200,0]},
  {key:'phantom-key',pack:'In-law boundaries',title:'The phantom key',question:'Your in-laws used an undisclosed copy of your key to enter while you were showering. What do you do?',a:['Spend $180 changing the locks and reviewing access.','The undisclosed key no longer opens the door.','Your spouse argues that the change treats their parents as unwelcome, exposing a disagreement about privacy.'],b:['Confront them from the bathroom doorway, wrapped in a towel.','The timing makes the invasion of privacy unmistakable.','They retell the awkward confrontation at gatherings instead of acknowledging the unauthorized entry.'],cost:[180,0]},
  {key:'ex-invitation',pack:'In-law boundaries',title:'The ex invitation',question:'Your mother-in-law invites your spouse’s ex to dinner after repeated comparisons between you. What do you do?',a:['Say you will leave unless the situation is addressed.','Your spouse must respond to a clearly stated limit.','The dinner becomes an argument over whether the limit is fair.'],b:['Flirt with the ex to disrupt the comparison.','The mother-in-law’s planned dynamic changes.','Your spouse feels hurt and insecure, and the argument continues on the way home.']},
  {key:'nursery',pack:'In-law boundaries',title:'The nursery takeover',question:'In this parenting vignette, the in-laws redecorate your planned nursery without asking. What do you do?',a:['Move their purchases out into the driveway.','You reclaim control of the room.','They focus on the public rejection and accuse you of rejecting the family itself.'],b:['Sell the unwanted furniture and plan to replace it.','You redirect the gifts toward the nursery you wanted.','They ask to see the furniture on their next visit. Avoiding the first conversation creates another one.']},
  {key:'name-game',pack:'In-law boundaries',title:'The name game',question:'Your father-in-law repeatedly calls you by the ex’s name or an unwanted nickname. What do you do?',a:['Use a mocking nickname for him in return.','He notices how personal the disrespect feels.','He demands respect for his age without addressing your request about your own name.'],b:['Wear a large name sticker to family events.','Guests can see the name he claims to forget.','Your spouse asks you to stop embarrassing the family instead of addressing the repeated behavior.']},
  {key:'unwanted-advice',pack:'In-law boundaries',title:'The unwanted advice',question:'At dinner, your father-in-law says your spouse should have married someone wealthier. What do you do?',a:['List his own financial mistakes.','The criticism stops while attention shifts to him.','He remembers the humiliation and brings it into later disagreements.'],b:['Look to your spouse to respond.','You give your spouse a clear opportunity to support you.','Their response depends on existing loyalty: support can soften the conflict, while silence adds strain to the relationship.']},
  {key:'financial-audit',pack:'In-law boundaries',title:'The financial audit',question:'Your in-laws offer help buying a home only if you hand over private financial records. What do you do?',a:['Refuse the money and the inspection.','Your financial information remains private.','The home purchase is delayed, and your spouse questions whether the cost of independence is shared fairly.'],b:['Show an obviously satirical budget full of absurd expenses.','You make your objection impossible to miss.','The in-laws treat the joke as proof that you are irresponsible, further weakening trust.']},
  {key:'diet-police',pack:'In-law boundaries',title:'The diet police',question:'In this parenting vignette, your mother-in-law ignores agreed food rules and criticizes your cooking. What do you do?',a:['Discard the food she brought in front of her.','You enforce the stated rule for this meal.','She frames the confrontation as being prevented from bonding with the children.'],b:['Refuse to handle meal planning until your spouse addresses the conflict.','Your spouse has to face the practical burden instead of dismissing it.','The household routine becomes strained, and the original agreement still needs a direct conversation.']},
  {key:'just-how-they-are',pack:'In-law boundaries',title:'That is just how they are',question:'Your spouse dismisses another boundary violation with “You know how they get. Ignore it.” What do you do?',a:['Spend $200 on a weekend hotel stay and explain why.','You create distance and make clear that the situation cannot continue unchanged.','The in-laws describe the stay as abandonment, and your spouse must decide whether to engage with the problem.'],b:['Mirror the intrusive behavior and use the same excuse.','You demonstrate the double standard.','Retaliation makes the household less tolerable and drains your own emotional capacity as well.'],cost:[200,0]}
];

const MONEY_CONFLICTS:PackedConflict[]=[
  {key:'sweat-equity',pack:'Money and business',title:'The sweat-equity betrayal',question:'After five years running landscaping crews, you learn the parents have given the business to Casey, who has never worked a shift. What do you do?',a:['Quit and plan a competing business.','You stop providing unrecognized labor and can pursue your own work.','The family threatens a dispute over customers and employment obligations. Starting a successful company is not guaranteed.'],b:['Stay and stop covering for Casey’s decisions.','Casey must face problems without your invisible rescue.','The business loses clients and cuts work. Watching someone fail also threatens your own income.']},
  {key:'identity-theft',pack:'Money and business',title:'The identity theft',question:'While applying for a mortgage, you discover overdue accounts apparently opened by a parent using your identity. What do you do?',a:['Report the suspected fraud and dispute the accounts.','You begin documenting the problem and challenging responsibility.','The family calls it betrayal. Investigations and credit corrections take an uncertain course; your house purchase is not instantly restored.'],b:['Pay $600 toward the accounts and avoid confronting the parent.','An immediate payment is made without a family confrontation.','The cost comes from your savings, and the underlying identity misuse remains unresolved.'],cost:[0,600]},
  {key:'register',pack:'Money and business',title:'The register raid',question:'Your uncle takes money from the family business register, but your pay is being docked for the shortage. What do you do?',a:['Present the transaction records documenting the missing money.','The family can no longer pretend there is no evidence.','The parents excuse the uncle and retaliate against you at work instead of addressing the losses.'],b:['Take money from the safe to offset your docked pay.','You recover some of what you feel you were denied.','You create a second theft allegation. Your uncle tries to blame all the losses on you.']},
  {key:'hostage-house',pack:'Money and business',title:'The hostage house',question:'You and Casey inherit a house together. Casey occupies it, refuses to discuss a sale, and moves friends in. What do you do?',a:['Spend $400 seeking an independent legal route to resolve ownership.','You begin a process outside the sibling stalemate.','The dispute grows expensive and Casey becomes hostile. A sale, its timing, and the final proceeds remain uncertain.'],b:['Move into the house and force a daily confrontation.','You assert a presence instead of waiting for Casey to cooperate.','The home becomes a tense place to live. Every practical disagreement is tangled with the inheritance.'],cost:[400,0]},
  {key:'nepotism',pack:'Money and business',title:'The nepotism hire',question:'The parents hire your inexperienced cousin above your salary and tell you to train them at the family warehouse. What do you do?',a:['Withhold training and let their mistakes become visible.','The skills gap can no longer be hidden by your extra work.','Inventory failures affect everyone, and the parents blame you for setting the cousin up to fail.'],b:['Quietly do both jobs.','The warehouse keeps functioning for now.','The cousin receives the credit and a promotion while you become exhausted and increasingly resentful.']},
  {key:'trust-warden',pack:'Money and business',title:'The trust fund warden',question:'An inheritance is held in a trust administered by an aunt who uses requests for money to police your life. What do you do?',a:['Spend $500 seeking independent advice about challenging the arrangement.','You learn there may be options beyond complying with her demands.','A dispute may consume time and money without delivering the control you hoped for.'],b:['Pretend to live exactly as she demands.','Her scrutiny eases and a requested distribution seems more likely.','Maintaining the performance strains your relationships and makes each new request another opportunity for control.'],cost:[500,0]},
  {key:'secret-lien',pack:'Money and business',title:'The secret lien',question:'Casey transfers estate property to you without disclosing a large outstanding tax claim. What do you do?',a:['Challenge the undisclosed transfer and seek an independent review.','You stop treating the gift as an uncomplicated benefit.','Casey calls you ungrateful. Ownership and liability remain disputed rather than disappearing with another signature.'],b:['Spend $900 toward resolving the claim and keep pursuing the property.','You make a payment toward a possible long-term asset.','Your savings shrink before the property produces any income. Its eventual value is still uncertain.'],cost:[0,900]},
  {key:'vehicle-trap',pack:'Money and business',title:'The vehicle trap',question:'A car registered in your name is used by Casey, who has left a pile of unpaid tickets and tolls. What do you do?',a:['Document the arrangement and seek a legitimate way to end it.','You begin addressing control of the vehicle and the outstanding charges.','Casey treats the boundary as an attack. Existing charges are not automatically erased.'],b:['Confront Casey about returning and selling the car to cover the charges.','You propose using the asset to address the cost.','Casey disputes who can sell it and demands the proceeds. The financial problem becomes a bitter ownership conflict.']},
  {key:'bait-loan',pack:'Money and business',title:'The bait-and-switch loan',question:'You co-signed what you were told was a business loan, then discover the money paid a parent’s concealed personal bills. What do you do?',a:['Spend $400 seeking advice and challenging the deception.','You stop accepting the parent’s account without scrutiny.','The dispute threatens family relationships and costs money. Challenging the parent does not automatically release the loan obligation.'],b:['Stop making payments to punish the parent.','You refuse to keep absorbing the cost in silence.','The account falls further behind. Your own finances face consequences alongside the parent’s.'],cost:[400,0]},
  {key:'deathbed',pack:'Money and business',title:'The deathbed blackmail',question:'A wealthy relative offers an inheritance if you promise to leave your partner. What do you do?',a:['Make the promise while planning not to keep it.','You remain a possible beneficiary without intending to end the relationship.','A recording of the promise emerges. Relatives use it to challenge your account, and your partner questions the bargain.'],b:['Refuse the condition and defend the relationship.','Your partner hears that the relationship is not for sale.','You are removed from the promised inheritance. Loyalty has a financial cost without guaranteeing a perfect relationship.']}
];

const RETURN_CONFLICTS:PackedConflict[]=[
  {key:'funeral-crasher',pack:'Estrangement',title:'The funeral crasher',question:'After a decade without contact, Casey arrives at a parent’s funeral demanding a front-row seat and a speaking slot. What do you do?',a:['Ask the funeral director to enforce the agreed arrangements.','You protect the planned service from an unnegotiated takeover.','Casey argues outside and relatives divide over whether the boundary was fair.'],b:['Allow Casey a speaking slot.','You avoid an immediate confrontation at the entrance.','The speech turns into an account of old grievances. Mourners disagree over whether it was honesty or an ambush.']},
  {key:'ransom-grandchild',pack:'Estrangement',title:'The unexpected grandchild',question:'In this later-life vignette, an estranged adult child returns with a grandchild you have never met and asks for unlimited childcare. What do you do?',a:['Offer contact with clear limits on childcare.','You distinguish wanting a relationship from agreeing to be permanently on call.','The parent withdraws again. You do not know when contact will resume.'],b:['Take on the childcare without an agreement.','You begin a warm relationship with the child.','The visits become longer and the parent harder to reach. Affection and an unsustainable workload now coexist.']},
  {key:'apology-tour',pack:'Estrangement',title:'The apology tour',question:'A relative who hurt you returns claiming spiritual transformation and asks everyone to accept a blanket apology at dinner. What do you do?',a:['Ask them to acknowledge one specific event.','You look for accountability rather than accepting a slogan.','They become defensive and accuse you of refusing to move on. The reunion ends in conflict.'],b:['Accept the apology to keep the evening calm.','Dinner continues without confrontation.','They treat reconciliation as permission to ask for your spare room, before trust has been rebuilt.']},
  {key:'amnesia-act',pack:'Estrangement',title:'The amnesia act',question:'A relative who cut everyone off five years ago arrives at Thanksgiving and behaves as though nothing happened. What do you do?',a:['Ask to address the absence before pretending everything is normal.','The missing history is acknowledged.','The parents accuse you of spoiling the reunion rather than making room for the question.'],b:['Introduce yourself as though they are a stranger.','You signal how distant the relationship has become.','They experience the gesture as ridicule and accuse you of making the return impossible.']},
  {key:'medical-return',pack:'Estrangement',title:'The medical return',question:'A parent who abandoned you asks whether you would consider testing as a possible stem-cell donor. What do you do?',a:['Decline contact and testing.','You preserve your choice about your body and involvement.','Some relatives pressure you, and conflicting feelings remain. Their accusations do not determine your medical obligations.'],b:['Agree to discuss testing with an independent care team.','You explore whether donation is possible without promising an outcome.','The parent treats your willingness as an entitlement. You still need boundaries, regardless of compatibility or whether donation occurs.']},
  {key:'rebrand',pack:'Estrangement',title:'The social media rebrand',question:'Casey built an online following with disputed stories about you and now wants to film a reconciliation. What do you do?',a:['Agree to appear and challenge their account on camera.','Your version reaches some of the audience.','The confrontation attracts hostile attention. Publishing evidence does not guarantee the audience will treat you fairly.'],b:['Refuse filming and send a written boundary about contact.','You do not consent to becoming content.','Casey portrays the refusal as censorship. The boundary is clear even though it cannot control their audience.']},
  {key:'inheritance-vulture',pack:'Estrangement',title:'The inheritance vulture',question:'An estranged cousin arrives during a grandparent’s hospice care and immediately pushes for private conversations about the estate. What do you do?',a:['Raise the concern with the care team and ask that the patient’s preferences guide visits.','You bring the pressure to people who can address it appropriately.','The cousin alleges you are excluding them for money. Family suspicion grows.'],b:['Stay out of the cousin’s visits.','You avoid a bedside confrontation.','You later learn they pressed for changes to the will. Whether anything is valid remains unresolved.']},
  {key:'cult-return',pack:'Estrangement',title:'The cult escapee',question:'Casey leaves a controlling group and arrives at your door with no stable place to stay. What do you do?',a:['Offer a temporary room and discuss a support plan.','Casey gets immediate shelter and a familiar connection.','Group habits and beliefs still affect daily life. Sharing a home requires boundaries and more support than you alone can provide.'],b:['Help seek specialist support without offering a room.','You offer help while protecting the limits of your household.','Casey feels rejected and considers returning to the group. The relationship needs more than a referral, but the outcome is not predetermined.']},
  {key:'ghosted-ex',pack:'Estrangement',title:'The ghosted ex-spouse',question:'Casey’s ex, who disappeared leaving debts and hurt behind, arrives at a barbecue because Mom invited them. What do you do?',a:['Ask Mom and the ex to leave.','Casey sees you taking their distress seriously.','Relatives divide over your demand and the gathering breaks apart.'],b:['Leave quietly with Casey.','You help Casey step out of the unwanted encounter.','Those who stay tell their own version of why you left, while Casey worries about being misrepresented.']},
  {key:'secret-milestone',pack:'Estrangement',title:'The secret milestone',question:'In this parenting vignette, an estranged parent appears uninvited at your child’s graduation and asks for family photos. What do you do?',a:['Ask event staff to help enforce the boundary.','You protect the arrangement your household chose.','The confrontation draws attention at a moment you wanted centered on the graduate.'],b:['Agree to one photograph and then leave.','You keep the interaction brief without a public scene.','The parent later displays the photograph as evidence of a closeness you have not agreed to restore.']}
];
const ADDICTION_CONFLICTS:PackedConflict[]=[
  {key:'three-am',pack:'Addiction and cover-ups',title:'The 3 AM DUI call',question:'An intoxicated relative says they crashed into a ditch and wants you to get them away before anyone notices. What do you do?',a:['Contact emergency services and prioritize anyone who may be hurt.','You seek help for an uncertain crash situation.','The relative blames you when the incident is investigated. The legal outcome is not yours to decide.'],b:['Agree to hide the incident and pick them up.','They feel protected from immediate scrutiny.','Possible injuries and damage remain unaddressed. The cover-up adds risk and another secret to the relationship.']},
  {key:'cabinet',pack:'Addiction and cover-ups',title:'The medicine cabinet raid',question:'You catch an aunt putting your prescription medicine in her pocket during a party. What do you do?',a:['Confront the taking where the family can hear.','The missing medicine cannot be dismissed as an accident.','She denies your account and relatives argue about the public confrontation.'],b:['Avoid confronting her and secure the remaining medicine.','You limit further access without a party-wide argument.','You are still missing medication, and the taking has not been addressed with her. Silence is not a complete solution.']},
  {key:'intervention',pack:'Addiction and cover-ups',title:'The hijacked intervention',question:'A meeting about Casey’s harmful gambling turns into accusations about the parents’ secrets. What do you do?',a:['Insist on returning to the gambling problem.','You refuse to let the original concern disappear.','Casey walks out, saying the meeting never made room for their perspective. Support and accountability remain unresolved.'],b:['Let the accusations take over.','Long-hidden hypocrisy is finally discussed.','The meeting ends without addressing the gambling, leaving the original concern alongside several new conflicts.']},
  {key:'pawned-ring',pack:'Addiction and cover-ups',title:'The pawned heirloom',question:'A relative has taken and pawned Grandma’s wedding ring while struggling with addiction. What do you do?',a:['Tell Grandma what happened.','She can decide how to respond to the loss and future access to her belongings.','The truth hurts her, and the relative angrily blames you for revealing it.'],b:['Spend $2000 recovering the ring without explaining.','The ring returns to Grandma.','The cost comes from your savings. The relative learns that you may quietly absorb another loss.'],cost:[0,2000]},
  {key:'borrowed-child',pack:'Addiction and cover-ups',title:'The borrowed child',question:'A sibling leaves a toddler for two hours, then remains unreachable for three days. What do you do?',a:['Seek help from child-welfare services about the child’s safety and care.','You bring an uncertain caregiving situation to people who can assess it.','The sibling calls it betrayal. Any agency response depends on the circumstances, not an automatic custody outcome.'],b:['Keep caring for the child without asking for outside help.','The child remains with a familiar caregiver for now.','Your responsibilities grow without an agreement or clear authority, and you have no reliable plan for the parent’s return.']},
  {key:'workplace',pack:'Addiction and cover-ups',title:'The workplace sabotage',question:'A relative you recommended for a job appears impaired and makes dangerous mistakes. What do you do?',a:['Report the observed safety concerns through the workplace process.','The employer can address the risk rather than relying on your cover.','The relative faces workplace consequences and blames you. Relatives ask you to make up for their lost income.'],b:['Cover their tasks and say nothing.','The immediate performance problem is less visible.','You become overloaded while the safety concern remains. Both jobs may be at risk.']},
  {key:'er-lie',pack:'Addiction and cover-ups',title:'The emergency-room lie',question:'A relative is in the ER after a suspected overdose. The care team asks what you know; the parents tell you to hide the substances involved. What do you do?',a:['Give the clinicians the information you actually know.','The team has information relevant to assessing and treating the patient.','The parents accuse you of exposing the family instead of recognizing why accurate information matters.'],b:['Withhold what you know to appease the parents.','The parents stop arguing with you for the moment.','The care team has less reliable information in an urgent situation. Your silence adds risk rather than guaranteeing privacy or a particular treatment outcome.']},
  {key:'bail-ultimatum',pack:'Addiction and cover-ups',title:'The bailout ultimatum',question:'A parent demands $1000 from your emergency savings toward Casey’s release after an arrest, promising that this time everything will change. What do you do?',a:['Decline the payment and set a limit on further calls.','Your emergency savings remain available for your own needs.','The parent calls you disloyal and threatens to exclude you from future help. Casey’s case continues independently.'],b:['Pay $1000 and ask Casey to hand over the car keys.','You contribute money and seek a concrete condition.','Casey breaks the agreement, and the payment has not produced the control or change you expected.'],cost:[0,1000]},
  {key:'enabling-spouse',pack:'Addiction and cover-ups',title:'The enabling spouse',question:'You discover Casey’s spouse is supplying substances they say keep Casey manageable. What do you do?',a:['Bring the concern to other family members.','The dynamic becomes visible beyond the couple.','They describe your concern as an attempt to break up the marriage and stop responding to you.'],b:['Ask the spouse about it privately.','You make space for an explanation without a public confrontation.','They deny the behavior and become more secretive. The private approach does not resolve the concern.']},
  {key:'forged-checks',pack:'Addiction and cover-ups',title:'The forged checks',question:'Bank records suggest a relative forged your signature and took your money. What do you do?',a:['Report the suspected fraud and challenge the transactions.','You begin a formal record and ask the bank to investigate.','The family pressures you to withdraw the complaint. Recovery of funds and legal outcomes are not guaranteed.'],b:['Absorb a $1200 loss and quietly stop their account access.','You reduce further access without a public accusation.','Your balance takes the loss, and the deception remains unaddressed within the family.'],cost:[0,1200]}
];
const MEDICAL_CONFLICTS:PackedConflict[]=[
  {key:'proxy-war',pack:'Medical proxies',title:'The proxy war',question:'You are the appointed proxy. A parent has a documented decision not to receive CPR, but relatives demand that you override it. What do you do?',a:['Ask the care team to follow the documented decision and explain its scope.','The patient’s preferences remain central. A DNR concerns CPR; other care is considered separately.','Some relatives accuse you of giving up. The conflict follows the family beyond the bedside.'],b:['Ask the team to change the plan to appease the relatives.','The loudest relatives feel supported for the moment.','The care team must still consider the patient’s wishes and clinical situation. You have created another dispute rather than authority to dictate treatment.']},
  {key:'iv-tampering',pack:'Medical proxies',title:'The supposed miracle cure',question:'Casey brings an unapproved substance into a hospital room and reaches toward a parent’s IV equipment. What do you do?',a:['Call the nurse immediately.','Trained staff can protect the patient and address the interference.','Casey accuses you of denying hope and may face restrictions on visits.'],b:['Stay silent to avoid arguing with Casey.','You avoid a direct confrontation for the moment.','The patient is exposed to an unsafe interference with care. Staff intervene when it is noticed, and your silence becomes part of the family dispute.']},
  {key:'hospice-heist',pack:'Medical proxies',title:'The hospice heist',question:'While you keep vigil at the bedside, siblings are removing valuable belongings from the parent’s home without an agreement. What do you do?',a:['Raise the concern with someone responsible for protecting the property.','The removal is challenged rather than quietly accepted.','The siblings say you cared more about objects than their goodbye. Ownership and authority still need clarification.'],b:['Stay at the bedside and leave the property dispute for later.','You remain present with the parent.','Several sentimental belongings are gone when you return, and recovering them becomes another conflict.']},
  {key:'facebook-martyr',pack:'Medical proxies',title:'The Facebook martyr',question:'An estranged sibling photographs themself beside an unconscious parent and starts criticizing your caregiving. What do you do?',a:['Ask staff to help protect the patient’s privacy and end the confrontation.','The patient is treated as a person whose dignity matters.','The sibling posts that you excluded them, drawing criticism from people who saw only their version.'],b:['Stay quiet until the visit ends.','You avoid another bedside argument.','Relatives praise the public performance while your continuing care remains largely invisible.']},
  {key:'withheld-diagnosis',pack:'Medical proxies',title:'The withheld diagnosis',question:'Casey asks whether their illness is terminal after the parents have insisted everyone promise a quick recovery. What do you do?',a:['Answer honestly about what you know and offer to speak with the care team together.','Casey gets a chance to ask direct questions and express their own wishes.','The parents accuse you of destroying hope rather than respecting Casey’s request.'],b:['Repeat the reassurance you know may be misleading.','The parents’ preferred story remains intact for now.','Casey senses the uncertainty and loses trust when the discrepancy becomes clear. You missed a chance to support an honest conversation.']},
  {key:'uninsured',pack:'Medical proxies',title:'The uninsured bailout',question:'After a parent’s stroke, you are handed financial-guarantor paperwork during discussions about further care. You do not yet understand the obligations. What do you do?',a:['Ask for the terms and alternatives before agreeing to personal liability.','You avoid signing an obligation you do not understand.','Relatives call the questions selfish, adding pressure to an already urgent care discussion.'],b:['Sign without reviewing the terms.','The family sees an immediate gesture of commitment.','In this fictional contract, a $1500 obligation comes due later. The signature did not guarantee a particular quality of care.']},
  {key:'deathbed-rewrite',pack:'Medical proxies',title:'The deathbed rewrite',question:'During a period of fluctuating clarity, a parent asks you to arrange a last-minute will change excluding Casey. What do you do?',a:['Ask an independent professional to assess the request.','You avoid secretly treating the request as automatically valid.','Casey suspects your motives. The family argues about capacity and influence even before any change is made.'],b:['Delay without honestly discussing your concern.','No immediate change is made during the conflict.','The parent is angry about the delay. The existing estate plan and any later challenge remain unresolved.']},
  {key:'gatekeeper',pack:'Medical proxies',title:'The gatekeeper spouse',question:'A parent’s new spouse insists that all your visits be short and supervised. What do you do?',a:['Ask the care team to clarify the patient’s wishes and visiting arrangements.','You seek a route that does not depend solely on the spouse’s demands.','The spouse sees the request as a challenge and becomes more hostile.'],b:['Accept the proposed schedule.','You preserve some contact without a direct confrontation.','The limited visits leave important conversations unfinished, and resentment builds.']},
  {key:'proxy-trap',pack:'Medical proxies',title:'The proxy trap',question:'You learn you were named sole proxy after the siblings declined the role, but they still criticize every decision. What do you do?',a:['Discuss whether you can continue and ask how to arrange an appropriate alternative.','You acknowledge the limits of what you can carry.','The family becomes anxious about who will take responsibility. An orderly transition is still needed; nobody automatically steps up.'],b:['Keep the role and hide how overwhelmed you feel.','Decision-making continues without an immediate handover.','The workload and criticism accumulate. Good intentions do not make unlimited responsibility sustainable.']},
  {key:'grim-math',pack:'Medical proxies',title:'The grim math',question:'Relatives focus on the cost of a parent’s intensive care and the shrinking estate. The parent previously wanted treatment continued where appropriate. What do you do?',a:['Ask the team to center the patient’s wishes, prognosis, and appropriate care.','You resist making inheritance the reason for a medical decision.','Relatives blame you for costs even though the decisions belong within the clinical and proxy process.'],b:['Join the relatives in pressuring for withdrawal to preserve money.','The relatives view you as aligned with their financial priority.','The team does not treat inheritance as authority to end treatment. Your pressure damages trust and leaves a lasting moral conflict.']}
];
export const EXTRA_CONFLICTS=[...FAMILY_CONFLICTS,...MONEY_CONFLICTS,...RETURN_CONFLICTS,...ADDICTION_CONFLICTS,...MEDICAL_CONFLICTS];
